"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { PLANS } from "@/lib/plans";
import { Check, Clock3, Info, LoaderCircle, Pause, Play } from "lucide-react";

function subscribeMotion(callback: () => void) {
  const query = matchMedia("(prefers-reduced-motion: reduce)");
  query.addEventListener("change", callback);
  return () => query.removeEventListener("change", callback);
}
function motionSnapshot() {
  return matchMedia("(prefers-reduced-motion: reduce)").matches;
}
const recipients = PLANS.PAID.campaignRecipients;
const initiallySent = recipients - 7;
const ringLength = 2 * Math.PI * 44;
const activity = [
  { name: "Priya Sharma", company: "Linear", sentAt: 4, threshold: 0 },
  { name: "Alex Morgan", company: "Notion", sentAt: 5, threshold: 0 },
  { name: "Sam Rivera", company: "Figma", sentAt: 6, threshold: 0 },
  {
    name: "Jordan Lee",
    company: "Vercel",
    sentAt: 7 + 8 / 7,
    threshold: initiallySent + 1,
  },
  {
    name: "Riya Patel",
    company: "Canva",
    sentAt: 7 + 16 / 7,
    threshold: initiallySent + 2,
  },
];

export function BatchProgressCard() {
  const reduced = useSyncExternalStore(
    subscribeMotion,
    motionSnapshot,
    () => true,
  );
  const [clock, setClock] = useState({ elapsed: 0, replay: true });
  const [paused, setPaused] = useState(false);
  const card = useRef<HTMLDivElement>(null);
  const arc = useRef<SVGCircleElement>(null);
  const sentBar = useRef<HTMLSpanElement>(null);
  const queuedBar = useRef<HTMLSpanElement>(null);
  const elapsed = useRef(0);
  const seconds = reduced ? 8 : Math.min(clock.elapsed, 8);
  const sent = Math.min(
    recipients,
    initiallySent + Math.floor((7 * seconds) / 8),
  );
  const queued = recipients - sent;
  const countdown = Math.max(0, Math.ceil(8 - seconds));
  const done = sent === recipients;
  const batchSeconds = 7 + seconds;

  useEffect(() => {
    const element = card.current;
    if (!element) return;
    let visible = !window.IntersectionObserver;
    let frame: number | undefined;
    let timer: ReturnType<typeof setInterval> | undefined;
    let lastTick = performance.now();
    const paint = (milliseconds: number) => {
      const progress = Math.min(milliseconds / 1000, 8);
      const fractionalSent = initiallySent + (7 * progress) / 8;
      if (arc.current) {
        arc.current.style.strokeDasharray = `${((7 + progress) / 15) * ringLength} ${ringLength}`;
      }
      if (sentBar.current) {
        sentBar.current.style.width = `${(fractionalSent / recipients) * 100}%`;
      }
      if (queuedBar.current) {
        queuedBar.current.style.width = `${(Math.min(3, recipients - fractionalSent) / recipients) * 100}%`;
      }
    };
    const stop = () => {
      if (timer !== undefined) {
        elapsed.current =
          (elapsed.current + performance.now() - lastTick) % 12_000;
        paint(elapsed.current);
      }
      if (frame !== undefined) cancelAnimationFrame(frame);
      frame = undefined;
      clearInterval(timer);
      timer = undefined;
    };
    const tick = () => {
      const now = performance.now();
      elapsed.current = (elapsed.current + now - lastTick) % 12_000;
      lastTick = now;
      setClock({
        elapsed: elapsed.current / 1000,
        replay: elapsed.current < 250,
      });
    };
    const animate = (now: number) => {
      paint((elapsed.current + now - lastTick) % 12_000);
      frame = requestAnimationFrame(animate);
    };
    const sync = () => {
      const suspended = reduced || paused || !visible || document.hidden;
      element.dataset.suspended = String(suspended);
      if (suspended) stop();
      else if (timer === undefined) {
        lastTick = performance.now();
        timer = setInterval(tick, 250);
        frame = requestAnimationFrame(animate);
      }
    };
    if (reduced) paint(8_000);
    else paint(elapsed.current);
    const observer = window.IntersectionObserver
      ? new IntersectionObserver(([entry]) => {
          visible = entry.isIntersecting;
          element.dataset.visible = String(visible);
          sync();
        })
      : null;
    observer?.observe(element);
    sync();
    document.addEventListener("visibilitychange", sync);
    return () => {
      stop();
      observer?.disconnect();
      document.removeEventListener("visibilitychange", sync);
    };
  }, [reduced, paused]);

  return (
    <div className="landing-dashboard-perspective max-sm:hidden">
      <div
        ref={card}
        className="landing-batch"
        data-done={done}
        data-paused={paused}
        data-visible="true"
        data-reset={clock.replay}
      >
        <div className="landing-batch-summary">
          <div className="landing-batch-header flex items-center justify-between flex-wrap gap-2 [@media(min-width:_1024px)_and_(max-height:_800px)]:gap-1.5">
            <span className="landing-batch-label">Batch progress</span>
            <span
              className={`landing-status inline-flex items-center gap-[7px] py-2 px-3.5 rounded-full text-[13px] [background:var(--color-landing-background-114)] [@media(max-width:_639px)]:text-[10px] [@media(max-width:_639px)]:gap-[5px] [@media(max-width:_639px)]:py-1.5 [@media(max-width:_639px)]:px-2 ${done ? "is-complete" : "is-sending"}`}
            >
              <span
                className="landing-status-dot rounded-[50%] [background:currentColor] w-[9px] h-[9px] shadow-[0_0_12px_currentColor] [@media(max-width:_639px)]:w-1.5 [@media(max-width:_639px)]:h-1.5"
                aria-hidden="true"
              />
              {done ? "Batch completed" : "Sending emails"}
            </span>
          </div>
          <p className="sr-only">
            Illustrative demo: a batch of {recipients} emails being sent one by
            one.
          </p>
          <div className="landing-batch-body">
            <div
              className="landing-ring"
              role="img"
              aria-label={`Example batch: ${sent} of ${recipients} emails sent, ${queued} queued, 0 failed`}
            >
              <div className="landing-ring-shadow w-full h-full">
                <svg
                  width="132"
                  height="132"
                  viewBox="0 0 100 100"
                  className="landing-ring-svg [@media(max-width:_1199px)_and_(min-width:_1024px)]:w-25 [@media(max-width:_1199px)_and_(min-width:_1024px)]:h-25 w-full h-full"
                  aria-hidden="true"
                >
                  <circle
                    cx="50"
                    cy="50"
                    r="44"
                    fill="none"
                    stroke="var(--landing-line3)"
                    strokeWidth="10"
                  />
                  <circle
                    ref={arc}
                    className="landing-progress-arc"
                    cx="50"
                    cy="50"
                    r="44"
                    fill="none"
                    stroke="var(--landing-accent)"
                    strokeWidth="10"
                    strokeLinecap="round"
                    strokeDasharray={`${(7 / 15) * ringLength} ${ringLength}`}
                  />
                </svg>
              </div>
              <div
                className="landing-ring-center absolute inset-3.5 grid place-items-center"
                aria-hidden="true"
              >
                <div
                  className={`landing-countdown ${done ? "is-complete" : ""}`}
                  aria-live="off"
                >
                  {done && (
                    <span className="landing-completion-badge">
                      <span className="landing-completion-ripple absolute inset-0 [border:2px_solid_var(--color-landing-landing-complete-gradient-17)] rounded-[50%] opacity-[0]" />
                      <Check
                        className="landing-completion-check"
                        size={22}
                        strokeWidth={2.5}
                        aria-hidden="true"
                      />
                    </span>
                  )}
                  <span
                    className={`landing-countdown-value ${done ? "sr-only" : ""}`}
                  >
                    00:{String(countdown).padStart(2, "0")}
                  </span>
                  <small>{done ? "All Sent" : "EST. LEFT"}</small>
                </div>
              </div>
            </div>
            <div className="landing-batch-details flex-1 min-w-0 [@media(max-width:_639px)]:w-full">
              <div
                className="landing-segmented-bar flex rounded-full overflow-hidden [background:var(--landing-line3)] h-3"
                aria-hidden="true"
              >
                <span
                  ref={sentBar}
                  className="landing-bar-sent [background:var(--landing-green)]"
                  style={{ width: `${(initiallySent / recipients) * 100}%` }}
                />
                <span
                  ref={queuedBar}
                  className="landing-bar-queued [background:var(--landing-amber)]"
                  style={{
                    width: `${(3 / recipients) * 100}%`,
                  }}
                />
              </div>
              <div className="landing-stat-grid">
                {[
                  {
                    label: "Sent",
                    value: sent,
                    sub: "Accepted by Gmail",
                    color: "var(--landing-green)",
                  },
                  {
                    label: "Queued",
                    value: queued,
                    sub: "Waiting",
                    color: "var(--landing-amber)",
                  },
                  {
                    label: "Failed",
                    value: 0,
                    sub: "Needs attention",
                    color: "var(--landing-red)",
                  },
                ].map(({ label, value, sub, color }) => (
                  <div className="landing-stat" key={label}>
                    <span className="landing-stat-label">
                      <i style={{ background: color }} aria-hidden="true" />
                      {label}
                    </span>
                    <span className="landing-stat-value">{value}</span>
                    <span className="landing-stat-sub">
                      <Clock3 size={15} aria-hidden="true" />
                      {sub}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
          <div className="landing-batch-meta">
            <span>Elapsed 0m {Math.floor(batchSeconds)}s</span>
            <span>Remaining ~{countdown}s</span>
            <span>
              {sent} of {recipients} sent
            </span>
          </div>
          <p className="landing-batch-footnote">
            <Info size={18} aria-hidden="true" /> Each recipient gets a separate
            email from your Gmail, one after another.
          </p>
        </div>
        <div className="landing-batch-activity">
          <div className="landing-activity-heading flex items-center justify-between [margin-block:22px_8px] [margin:22px_0_8px] mt-0">
            <h2>Recent activity</h2>
            <span>Demo batch</span>
          </div>
          <ul className="landing-activity">
            {activity.map((person) => {
              const delivered = sent >= person.threshold;
              const sending = !delivered && sent === person.threshold - 1;
              const StatusIcon = delivered
                ? Check
                : sending
                  ? LoaderCircle
                  : Clock3;
              return (
                <li
                  key={person.name}
                  data-status={
                    delivered ? "delivered" : sending ? "sending" : "queued"
                  }
                >
                  <span className="landing-activity-icon">
                    {person.name.charAt(0)}
                  </span>
                  <span className="landing-activity-person">
                    <strong>{person.name}</strong>
                    <span>{person.company}</span>
                  </span>
                  <span className="landing-activity-status">
                    <StatusIcon size={14} aria-hidden="true" />
                    {delivered ? "Delivered" : sending ? "Sending…" : "Queued"}
                  </span>
                  <span className="landing-activity-time text-right [font-variant-numeric:tabular-nums] w-12.5 text-[11px] [@media(max-width:_639px)]:w-7.5 [@media(max-width:_639px)]:text-[9px]">
                    {delivered
                      ? `${Math.max(0, Math.floor(batchSeconds - person.sentAt))}s ago`
                      : "—"}
                  </span>
                </li>
              );
            })}
          </ul>
          {!reduced && (
            <button
              type="button"
              className="landing-demo-control inline-flex items-center gap-1.5 min-h-11 text-[var(--landing-faint)] cursor-pointer css-hover:text-[var(--landing-fg)] mt-1.5 text-[11px]"
              aria-label={
                paused ? "Resume batch animation" : "Pause batch animation"
              }
              onClick={() => setPaused((value) => !value)}
            >
              {paused ? (
                <Play size={14} aria-hidden="true" />
              ) : (
                <Pause size={14} aria-hidden="true" />
              )}
              {paused ? "Resume demo" : "Pause demo"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
